<?php $labels=['geral'=>'Geral','caixas'=>'Caixas','clientes'=>'Clientes','pedidos'=>'Pedidos','itens'=>'Itens','estoque'=>'Estoque','entregadores'=>'Entregadores','garcons'=>'Garçons','areas'=>'Área de entrega']; ?>
<div class="wrap"><div class="page-title-row"><div><h2>Relatórios · <?= e($labels[$tipo]) ?></h2><p>Consulte os dados da operação e exporte pelo recurso de impressão do navegador.</p></div><button class="cxgo" onclick="window.print()">Imprimir / salvar PDF</button></div>
  <div class="report-tabs"><?php foreach($labels as $k=>$l): ?><a class="<?= $tipo===$k?'on':'' ?>" href="?r=admin_reports&tipo=<?= $k ?>&de=<?= e($de) ?>&ate=<?= e($ate) ?>"><?= e($l) ?></a><?php endforeach; ?></div>
  <form class="orders-toolbar"><input type="hidden" name="r" value="admin_reports"><input type="hidden" name="tipo" value="<?= e($tipo) ?>"><label>De <input type="date" name="de" value="<?= e($de) ?>"></label><label>Até <input type="date" name="ate" value="<?= e($ate) ?>"></label><button class="order-filter on">Aplicar período</button></form>
  <?php if($rows): $headers=array_keys($rows[0]); ?><div style="overflow:auto"><table class="report-table"><thead><tr><?php foreach($headers as $h): ?><th><?= e(ucwords(str_replace('_',' ',$h))) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($headers as $h): ?><td><?= e(is_numeric($row[$h])&&in_array($h,['total','valor','faturamento','saldo_inicial','saldo_informado','total_gasto'],true)?money($row[$h]):$row[$h]) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="cfgcard"><h3>Nenhum dado no período</h3><p>Os dados aparecerão aqui assim que houver movimentação.</p></div><?php endif; ?>
